  const state=report.versionRetentionState;
  const ids=new Set([...(state.cleanupCandidateVersionIds||[]),...(versionIds||[]).map(String)]);
  state.cleanupCandidateVersionIds=[...ids];
  state.updatedAt=new Date().toISOString();
